declare_lint_rule! {
    /// Enforces the use of the `sandbox` attribute on `<iframe>` elements.
    ///
    /// The `sandbox` attribute enables an extra set of restrictions for the content
    /// embedded in the iframe, protecting against malicious scripts and other security
    /// threats. An `<iframe>` without a `sandbox` attribute runs with the same
    /// privileges as the embedding page.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <iframe src="https://example.com"></iframe>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <iframe src="https://example.com" sandbox></iframe>
    /// ```
    ///
    /// ```html
    /// <iframe src="https://example.com" sandbox="allow-scripts"></iframe>
    /// ```
    ///
    /// ## Resources
    ///
    /// - [MDN: The Inline Frame element](https://developer.mozilla.org/en-US/docs/Web/HTML/Element/iframe#sandbox)
    ///
    pub UseIframeSandbox {
        version: "next",
        name: "useIframeSandbox",
        language: "html",
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for UseIframeSandbox {
    type Query = Ast<AnyHtmlElement>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = UseIframeSandboxOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        match node {
            AnyHtmlElement::HtmlElement(element) => {
                let opening = element.opening_element().ok()?;
                let tag_name = opening.tag_name()?;
                if !tag_name.text().eq_ignore_ascii_case("iframe") {
                    return None;
                }
                if opening.find_attribute_by_name("sandbox").is_none() {
                    return Some(());
                }
            }
            AnyHtmlElement::HtmlSelfClosingElement(element) => {
                let tag_name = element.tag_name()?;
                if !tag_name.text().eq_ignore_ascii_case("iframe") {
                    return None;
                }
                if element.find_attribute_by_name("sandbox").is_none() {
                    return Some(());
                }
            }
            _ => {}
        }

        None
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Iframe doesn't have the sandbox attribute."
                },
            )
            .note(markup! {
                "The sandbox attribute enables an extra set of restrictions for the content in the iframe, protecting against malicious scripts and other security threats."
            })
            .note(markup! {
                "Provide a sandbox attribute when using iframe elements."
            }),
        )
    }
}
