pub fn name_value_token(&self) -> SyntaxResult<JsSyntaxToken> {
        match self {
            Self::JsxMemberName(member) => member.member()?.value_token(),
            Self::JsxName(name) => name.value_token(),
            Self::JsxNamespaceName(name) => name.name()?.value_token(),
